async function run(wf, args) {
{
  const { tasks, batches } = args ?? {};

  const FIXED_RULES = `You are an isolated subagent implementing ONE task of an approved project. You have no
prior conversation context — everything you need is in your task file + the rules below. Do not
ask for clarification; make a reasonable, documented decision where the task is ambiguous.

- FIRST read your task file with the read tool (the 'task file' path in the Task block). It is
  your full brief — goal, context files, requirements with their allocated failing tests,
  conventions, constraints — and the source of truth. Never guess or reconstruct the brief from
  memory.

- Work at the repo root (your cwd). Leave all changes UNCOMMITTED — a later review reads the diff.
- Touch only the files named in your task's \\\`owned_files\\`;

  const RETURN_SCHEMA = {
    type: 'object',
    required: ['changed_files', 'satisfied_requirements'],
    properties: {
      changed_files: { type: 'array', items: { type: 'object', required: ['file', 'lines'], properties: { file: { type: 'string' }, lines: { type: 'string' } } } },
      satisfied_requirements: { type: 'array', items: { type: 'string' } },
      deviations: { type: 'array', items: { type: 'string' } },
    },
  };

  // Build a SMALL per-task prompt. The task brief lives in a file the subagent
  // reads (promptFile, a repo-relative path), so run_workflow args stay tiny
  // and the tool-call JSON is never corrupted by an embedded task brief.
  function taskPrompt(t) {
    if (t == null || typeof t !== 'object') throw new Error('implement task must be an object');
    const id = t.id === undefined ? 'task' : String(t.id);
    if (typeof t.promptFile !== 'string' || t.promptFile.trim().length === 0) {
      throw new Error('implement task "' + id + '" is missing a promptFile path: write the task brief to a file and pass its repo-relative path (keep args small)');
    }
    return [
      '## Task to implement',
      '- task id: ' + id,
      '- task name: ' + (t.name === undefined ? id : String(t.name)),
      '- task file: ' + t.promptFile,
      '',
      'Read the task file NOW with the read tool — it is your full task brief (goal, owned/forbidden files, requirements + their allocated failing tests, conventions, constraints). Then follow the fixed rules below.',
    ].join('\n');
  }

  const groups = batches ?? (tasks ? [tasks] : []);
  const results = [];

  for (let b = 0; b < groups.length; b++) {
    const label = groups.length > 1 ? 'batch-' + (b + 1) : 'implement';
    const done = await wf.phase(label, () => wf.parallel(
      groups[b].map(t => () => wf.runAgent({
        name: String(t?.id ?? 'task'),
        prompt: taskPrompt(t) + '\n\n' + FIXED_RULES,
        readOnly: false,
        modelHint: 'balanced',
        outputSchema: RETURN_SCHEMA,
      })),
    ));
    if (done.some(r => r === null)) return { status: 'failed', batch: b + 1 };
    results.push(...done.map(r => r.structured));
  }
  return { status: 'done', agents: results.length };
}
}
